-- Rules on a data-modifying WITH query's target: the query's own rewrite
-- checks RETURNING first, then PostgreSQL accepts only rules that leave
-- exactly one statement, naming the first offending rule in name order.
CREATE TABLE w413_a(a int); CREATE TABLE w413_b(a int);
CREATE RULE r_also AS ON INSERT TO w413_a DO ALSO INSERT INTO w413_b VALUES (NEW.a);
WITH w AS (INSERT INTO w413_a VALUES (1) RETURNING a) SELECT * FROM w;
CREATE RULE a_cond AS ON INSERT TO w413_a WHERE NEW.a > 5 DO INSTEAD INSERT INTO w413_b VALUES (NEW.a);
WITH w AS (INSERT INTO w413_a VALUES (1) RETURNING a) SELECT * FROM w;
DROP RULE r_also ON w413_a;
WITH w AS (INSERT INTO w413_a VALUES (1) RETURNING a) SELECT * FROM w;
DROP RULE a_cond ON w413_a;
CREATE RULE r_nothing AS ON UPDATE TO w413_a DO INSTEAD NOTHING;
WITH w AS (UPDATE w413_a SET a = 2 RETURNING a) SELECT * FROM w;
CREATE RULE r_multi AS ON DELETE TO w413_a DO INSTEAD (DELETE FROM w413_b; DELETE FROM w413_b WHERE a = 1);
WITH w AS (DELETE FROM w413_a RETURNING a) SELECT * FROM w;
DROP RULE r_multi ON w413_a;
CREATE RULE r_notify AS ON DELETE TO w413_a DO INSTEAD NOTIFY foo;
WITH w AS (DELETE FROM w413_a) SELECT 1;
DROP RULE r_notify ON w413_a;
CREATE RULE r_also_notify AS ON DELETE TO w413_a DO ALSO NOTIFY foo;
WITH w AS (DELETE FROM w413_a) SELECT 1;
DROP RULE r_also_notify ON w413_a;
CREATE RULE r_inst AS ON DELETE TO w413_a DO INSTEAD DELETE FROM w413_b;
CREATE RULE r_inst2 AS ON DELETE TO w413_a WHERE OLD.a > 3 DO ALSO DELETE FROM w413_b;
WITH w AS (DELETE FROM w413_a) SELECT 1;
CREATE RULE b_c AS ON INSERT TO w413_a WHERE NEW.a > 5 DO INSTEAD NOTHING;
WITH w AS (INSERT INTO w413_a VALUES (1)) SELECT 1;
WITH w AS (INSERT INTO w413_a VALUES (1)) INSERT INTO w413_b SELECT 1;
DROP RULE b_c ON w413_a;
DROP RULE r_nothing ON w413_a;
CREATE RULE r1 AS ON UPDATE TO w413_b DO INSTEAD UPDATE w413_a SET a = NEW.a RETURNING *;
CREATE RULE r2 AS ON UPDATE TO w413_b DO INSTEAD UPDATE w413_a SET a = NEW.a + 1 RETURNING *;
WITH w AS (UPDATE w413_b SET a = 3 RETURNING a) SELECT * FROM w;
WITH w AS (UPDATE w413_b SET a = 3) SELECT 1;
-- An earlier query's rows are not written when a later one is rejected.
WITH v AS (INSERT INTO w413_a VALUES (40) RETURNING a), w AS (DELETE FROM w413_a) SELECT * FROM v;
SELECT * FROM w413_a ORDER BY a;
SELECT * FROM w413_b ORDER BY a;
DROP TABLE w413_a, w413_b;
